#!/usr/bin/env bash
# Documentation : « Qualité » en trois chapitres ; plages recalées (stockage), configuration et démarrage à jour.
# Prérequis : apply-fix-qualite.sh et apply-docs-interface.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-qualite.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/qualite/les-gardes-maison.mdx" 2>/dev/null | grep -qF "Les gardes maison"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "tsc -p tsconfig.json" "package.json" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-qualite.sh"; exit 1; }
grep -qF "La page courante, vue et entendue" "apps/web/content/docs/dev/interface/header.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-interface.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/configuration/package-json-et-monorepo.mdx" "apps/web/content/docs/dev/configuration/typescript-et-tsconfig.mdx" "apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/content/docs/dev/interface/accessibilite.mdx" "apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" "apps/web/content/docs/dev/stockage/enregistrer-ce-qui-est-arrive.mdx" "apps/web/content/docs/dev/stockage/modifier-sans-casser.mdx" "apps/web/content/docs/dev/stockage/signer-un-envoi.mdx" "apps/web/content/docs/dev/stockage/un-explorateur-sur-un-sac-de-cles.mdx")
EXPECT=("277bafd5743b:apps/web/content/docs/dev/configuration/package-json-et-monorepo.mdx" "2981f1d82d55:apps/web/content/docs/dev/configuration/typescript-et-tsconfig.mdx" "e1007b0157dd:apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "df48d105e7f2:apps/web/content/docs/dev/interface/accessibilite.mdx" "c9e64426fd6b:apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" "d4bf325a0ea9:apps/web/content/docs/dev/stockage/enregistrer-ce-qui-est-arrive.mdx" "67cc6f56ad15:apps/web/content/docs/dev/stockage/modifier-sans-casser.mdx" "5ce6d7209521:apps/web/content/docs/dev/stockage/signer-un-envoi.mdx" "32b4e9de09bf:apps/web/content/docs/dev/stockage/un-explorateur-sur-un-sac-de-cles.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/dev/qualite/la-chaine-pnpm-check.mdx" "apps/web/content/docs/dev/qualite/les-gardes-maison.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Les gardes maison" "apps/web/content/docs/dev/qualite/les-gardes-maison.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/qualite"
