# Table de l'index : ligne « Qualité », quel que soit son texte actuel.
F=apps/web/content/docs/dev/index.mdx
if ! git diff --quiet HEAD -- "$F"; then echo "❌ $F a des modifications non commitées"; restore; exit 1; fi
MODIFIED+=("$F")
python3 - "$F" <<'PY2'
import re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
new = "[\"Qualité\",\"En trois chapitres : la chaîne de pnpm check (des gardes rapides d’abord, trois projets TypeScript, le lint de tout le code écrit à la main, ce qu’elle ne voit pas) ; le typecheck et le lint (deux questions, le lint ramené à zéro, les règles du React Compiler) ; les gardes maison (quatre erreurs silencieuses et la recette d’une cinquième). Déboguer et tester : à venir.\",\"rédigée\"]"
s2, n = re.subn(r'\["Qualité","[^"]*","[^"]*"\]', lambda m: new, s)
assert n == 1, n
open(p, "w", encoding="utf-8").write(s2)
PY2
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
docs(qualite): trois chapitres — la chaîne de pnpm check, le typecheck et le lint, les gardes maison

- La chaîne de pnpm check (nouveau) : l'ordre des étapes, pourquoi effacer .next, trois projets
  TypeScript, le lint de tout le code écrit à la main, ce que le premier passage a trouvé, ce que
  la chaîne ne voit pas
- Le typecheck et le lint : extraits vivants à la place des blocs recopiés
- Les gardes maison (nouveau) : les quatre scripts pas à pas, et la recette d'une garde
- Configuration et démarrage à jour (scripts, tsconfig) ; plages recalées (stockage) ; index

